cat > /tmp/mk16.js <<'EOF'
const fs=require('fs');
const snips=[];
// matrix: nested list of depth d (tight, single block), then blank line, then block indented i spaces
for (const d of [1,2,3]) {
  let base = [];
  for (let k=0;k<d;k++) base.push(' '.repeat(4*k) + '- L'+(k+1));
  for (const i of [0,4,8,12,16,20]) {
    snips.push(base.join('\n') + '\n\n' + ' '.repeat(i) + 'X');
  }
}
fs.writeFileSync('/workspace/probes/nest-16.json', JSON.stringify(snips));
EOF
node /tmp/mk16.js && node /workspace/tools/probe.mjs --file /workspace/probes/nest-16.json
